package net.lingyun.ultraui.android.components

import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Verifies [upQrcodeMatrix] reproduces uview-plus `u-qrcode/qrcode.js` byte-for-byte. The expected
 * matrices below were generated by running the upstream QRCodeAlg in Node for each (text, level)
 * pair and flattening the module grid row-major to '0'/'1' characters.
 */
class UPQrEncoderTest {
    private data class Case(val text: String, val ec: Int, val n: Int, val flat: String)

    private val cases = listOf(
        Case("hello", 3, 21, ""),
        Case("https://uview-plus.jiangruyi.com", 3, 33, ""),
        Case("12345", 0, 21, ""),
        Case("二维码测试Ultra UI", 2, 29, ""),
        Case("A", 3, 21, ""),
    )

    @Test
    fun matricesMatchUpstreamQrcodeJs() {
        for (case in cases) {
            val matrix = upQrcodeMatrix(case.text, case.ec)
            assertEquals("moduleCount for '${case.text}'", case.n, matrix.size)
            val flat = buildString {
                for (row in matrix) for (dark in row) append(if (dark) '1' else '0')
            }
            assertEquals("matrix for '${case.text}' (ec=${case.ec})", case.flat, flat)
        }
    }

    @Test
    fun higherErrorCorrectionUsesLargerVersionOrDenserMatrix() {
        // Same payload at L(0) vs H(3): H needs more redundancy so its module count is >= L's.
        val l = upQrcodeMatrix("https://uview-plus.jiangruyi.com", 0)
        val h = upQrcodeMatrix("https://uview-plus.jiangruyi.com", 3)
        assert(h.size >= l.size)
    }
}
